function validate([mainTank, additionalTank]) {
  if (!Number.isInteger(mainTank) || mainTank < 1 || mainTank > 100) return 'mainTank is between 1 and 100.';
  if (!Number.isInteger(additionalTank) || additionalTank < 1 || additionalTank > 100) return 'additionalTank is between 1 and 100.';
  return null;
}

