function distanceTraveled(mainTank, additionalTank) {
  // Burn one liter at a time and check for a transfer after every fifth liter.
  let burned = 0;
  while (mainTank > 0) {
    mainTank--;
    burned++;
    if (burned % 5 === 0 && additionalTank > 0) {
      additionalTank--;
      mainTank++;
    }
  }
  return burned * 10;
}

