function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') return [pick(60, 100), pick(1, 100)];
  return [pick(1, 30), pick(1, rand() < 0.5 ? 3 : 12)];
}
